    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_message_template PRIMARY KEY (id),
    CONSTRAINT ck_message_template_channel CHECK (channel IN ('email', 'sms', 'push', 'in_app')),
    CONSTRAINT uq_message_template_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE comms.message_template IS 'Reusable message template for e-mail, SMS, push or in-app messages.';
COMMENT ON COLUMN comms.message_template.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN comms.message_template.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN comms.message_template.institution_id IS 'Institution (NULL = tenant-wide).';
COMMENT ON COLUMN comms.message_template.channel IS 'Delivery channel.';
