COMMENT ON COLUMN comms.message_template.subject IS 'Subject (e-mail).';
COMMENT ON COLUMN comms.message_template.body IS 'Body with placeholders.';
COMMENT ON COLUMN comms.message_template.external_template_id IS 'External provider-registered template id (e.g. SMS DLT template id).';
COMMENT ON COLUMN comms.message_template.is_active IS 'Whether usable.';
COMMENT ON COLUMN comms.message_template.created_at IS 'Row creation time.';
COMMENT ON COLUMN comms.message_template.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN comms.message_template.updated_at IS 'Last update time.';
COMMENT ON COLUMN comms.message_template.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN comms.message_template.deleted_at IS 'Soft-delete marker; NULL = live row.';
