CREATE TABLE comms.event (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    institution_id uuid,
    academic_year_id uuid,
    audience varchar(30) NOT NULL DEFAULT  'school',
    class_section_id uuid,
    audience_label varchar(120),
    title varchar(200) NOT NULL,
    description text,
    category varchar(30) NOT NULL DEFAULT  'other',
    location text,
    organised_by text,
    image_file_id uuid,
    color varchar(20),
    start_at timestamptz,
    end_at timestamptz,
    is_all_day boolean NOT NULL DEFAULT true,
    repeat_count integer NOT NULL DEFAULT 0,
    repeat_interval integer NOT NULL DEFAULT 0,
    repeat_unit varchar(30),
    url varchar(500),
    status varchar(30) NOT NULL DEFAULT  'inactive',
    cohort_id uuid,
    owner_user_id uuid,
    recurrence_rule varchar(500),
    for_all_members boolean NOT NULL DEFAULT true,
    staff_can_edit boolean NOT NULL DEFAULT false,
    importance varchar(30),
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_event PRIMARY KEY (id),
    CONSTRAINT ck_event_audience CHECK (audience IN ('school', 'class', 'alumni', 'tenant', 'cohort', 'personal')),
    CONSTRAINT ck_event_category CHECK (category IN ('cultural', 'education', 'exam', 'holiday', 'meeting', 'live_class', 'other')),
    CONSTRAINT ck_event_repeat_unit CHECK (repeat_unit IN ('day', 'week', 'month', 'year')),
    CONSTRAINT ck_event_status CHECK (status IN ('active', 'inactive')),
    CONSTRAINT ck_event_importance CHECK (importance IN ('high', 'medium', 'low')),
    CONSTRAINT ck_event_1 CHECK ((audience = 'cohort') = (cohort_id IS NOT NULL)),
    CONSTRAINT ck_event_2 CHECK ((audience = 'personal') = (owner_user_id IS NOT NULL)),
    CONSTRAINT uq_event_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE comms.event IS 'Calendar event (school event, holiday, exam, meeting, live class).';
