-- Intra-module foreign keys
ALTER TABLE comms.outbound_message ADD CONSTRAINT fk_outbound_message_template_id FOREIGN KEY (template_id, tenant_id) REFERENCES comms.message_template (id, tenant_id) ON DELETE SET NULL (template_id);
CREATE INDEX ix_outbound_message_template_id ON comms.outbound_message (template_id);
ALTER TABLE comms.in_app_notification ADD CONSTRAINT fk_in_app_notification_notification_type_id FOREIGN KEY (notification_type_id) REFERENCES comms.notification_type (id) ON DELETE RESTRICT;
CREATE INDEX ix_in_app_notification_notification_type_id ON comms.in_app_notification (notification_type_id);
ALTER TABLE comms.notice ADD CONSTRAINT fk_notice_background_id FOREIGN KEY (background_id, tenant_id) REFERENCES comms.notice_background (id, tenant_id) ON DELETE SET NULL (background_id);
CREATE INDEX ix_notice_background_id ON comms.notice (background_id);
ALTER TABLE comms.event_gallery_item ADD CONSTRAINT fk_event_gallery_item_event_id FOREIGN KEY (event_id, tenant_id) REFERENCES comms.event (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_event_gallery_item_event_id ON comms.event_gallery_item (event_id);
ALTER TABLE comms.conversation_participant ADD CONSTRAINT fk_conversation_participant_conversation_id FOREIGN KEY (conversation_id, tenant_id) REFERENCES comms.conversation (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_conversation_participant_conversation_id ON comms.conversation_participant (conversation_id);
ALTER TABLE comms.conversation_message ADD CONSTRAINT fk_conversation_message_conversation_id FOREIGN KEY (conversation_id, tenant_id) REFERENCES comms.conversation (id, tenant_id) ON DELETE CASCADE;
