-- === S1: one reaction table ===

CREATE TABLE comms.reaction (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    post_id uuid,
    comment_id uuid,
    user_id uuid NOT NULL,
    reaction varchar(30),
    is_saved boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_reaction PRIMARY KEY (id),
    CONSTRAINT ck_reaction_target CHECK (num_nonnulls(post_id, comment_id) = 1),
    CONSTRAINT ck_reaction_saved_on_post CHECK (comment_id IS NULL OR is_saved = false)
);
COMMENT ON TABLE comms.reaction IS 'A user''''s reaction to a post or to a comment (exclusive arc).';
COMMENT ON COLUMN comms.reaction.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN comms.reaction.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN comms.reaction.post_id IS 'Post reacted to (exactly one of post_id / comment_id).';
COMMENT ON COLUMN comms.reaction.comment_id IS 'Comment reacted to (exactly one of post_id / comment_id).';
COMMENT ON COLUMN comms.reaction.user_id IS 'Reacting user.';
COMMENT ON COLUMN comms.reaction.reaction IS 'Reaction kind (like, celebrate...).';
COMMENT ON COLUMN comms.reaction.is_saved IS 'Post bookmarked by the user (posts only).';
COMMENT ON COLUMN comms.reaction.is_active IS 'Reaction currently active (toggled off instead of deleted).';
COMMENT ON COLUMN comms.reaction.created_at IS 'Row creation time.';
COMMENT ON COLUMN comms.reaction.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN comms.reaction.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN comms.reaction.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN comms.reaction.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN comms.reaction.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE comms.reaction ADD CONSTRAINT fk_reaction_post_id FOREIGN KEY (post_id, tenant_id) REFERENCES comms.post (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_reaction_post_id ON comms.reaction (post_id);
ALTER TABLE comms.reaction ADD CONSTRAINT fk_reaction_comment_id FOREIGN KEY (comment_id, tenant_id) REFERENCES comms.post_comment (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_reaction_comment_id ON comms.reaction (comment_id);
CREATE UNIQUE INDEX uq_reaction_post ON comms.reaction (post_id, user_id) WHERE post_id IS NOT NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX uq_reaction_comment ON comms.reaction (comment_id, user_id) WHERE comment_id IS NOT NULL AND deleted_at IS NULL;

