-- === Module-local infrastructure (distributed deployment: no cross-schema access) ===
CREATE TABLE comms.idempotency_key (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    user_id uuid,
    operation_name varchar(120) NOT NULL,
    request_hash varchar(64),
    response_status smallint,
    response_body text,
    locked_at timestamptz,
    completed_at timestamptz,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_comms_idempotency_key PRIMARY KEY (id),
    CONSTRAINT uq_comms_idempotency_key_1 UNIQUE (tenant_id, idempotency_key)
);
COMMENT ON TABLE comms.idempotency_key IS 'Module-local idempotency store of the comms module: stored outcome of a write carrying an Idempotency-Key; replays return the stored response. Rows expire after 24h (cleanup job).';
COMMENT ON COLUMN comms.idempotency_key.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN comms.idempotency_key.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN comms.idempotency_key.idempotency_key IS 'Key sent by the client.';
COMMENT ON COLUMN comms.idempotency_key.user_id IS 'Caller.';
COMMENT ON COLUMN comms.idempotency_key.operation_name IS 'Operation the key was used on.';
COMMENT ON COLUMN comms.idempotency_key.request_hash IS 'Hash of the request body; a replay with a different body is rejected.';
COMMENT ON COLUMN comms.idempotency_key.response_status IS 'Stored HTTP status.';
COMMENT ON COLUMN comms.idempotency_key.response_body IS 'Stored response body.';
COMMENT ON COLUMN comms.idempotency_key.locked_at IS 'Set while the first attempt is still executing.';
COMMENT ON COLUMN comms.idempotency_key.completed_at IS 'When the stored response was written.';
COMMENT ON COLUMN comms.idempotency_key.expires_at IS 'When the row may be purged.';
COMMENT ON COLUMN comms.idempotency_key.created_at IS 'Row creation time.';
COMMENT ON COLUMN comms.idempotency_key.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN comms.idempotency_key.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN comms.idempotency_key.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN comms.idempotency_key.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN comms.idempotency_key.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE comms.idempotency_key ENABLE ROW LEVEL SECURITY;
ALTER TABLE comms.idempotency_key FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON comms.idempotency_key USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE comms.operation (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    operation_name varchar(120) NOT NULL,
    resource_type varchar(80),
    resource_id uuid,
    status varchar(20) NOT NULL DEFAULT 'running',
    progress_percent smallint,
    error_code varchar(60),
    error_message varchar(500),
    result_entity_type varchar(80),
    result_entity_id uuid,
    started_by_user_id uuid,
    started_at timestamptz NOT NULL DEFAULT now(),
    finished_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_comms_operation PRIMARY KEY (id),
    CONSTRAINT ck_comms_operation_status CHECK (status IN ('running', 'succeeded', 'failed', 'cancelled'))
);
COMMENT ON TABLE comms.operation IS 'Module-local long-running operation record of the comms module, returned by its async API calls; polled by clients until it finishes.';
COMMENT ON COLUMN comms.operation.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN comms.operation.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN comms.operation.operation_name IS 'Operation id as exposed by the API (module.Method).';
COMMENT ON COLUMN comms.operation.resource_type IS 'Kind of resource being worked on.';
COMMENT ON COLUMN comms.operation.resource_id IS 'Id of that resource.';
COMMENT ON COLUMN comms.operation.status IS 'running / succeeded / failed / cancelled.';
COMMENT ON COLUMN comms.operation.progress_percent IS 'Progress, when the job reports it.';
COMMENT ON COLUMN comms.operation.error_code IS 'Machine error code when failed.';
COMMENT ON COLUMN comms.operation.error_message IS 'Human error summary when failed.';
COMMENT ON COLUMN comms.operation.result_entity_type IS 'Kind of the produced record.';
COMMENT ON COLUMN comms.operation.result_entity_id IS 'Id of the produced record.';
COMMENT ON COLUMN comms.operation.started_by_user_id IS 'User who started it.';
COMMENT ON COLUMN comms.operation.started_at IS 'Start time.';
COMMENT ON COLUMN comms.operation.finished_at IS 'End time.';
COMMENT ON COLUMN comms.operation.created_at IS 'Row creation time.';
COMMENT ON COLUMN comms.operation.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN comms.operation.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN comms.operation.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN comms.operation.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN comms.operation.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE comms.operation ENABLE ROW LEVEL SECURITY;
ALTER TABLE comms.operation FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON comms.operation USING (tenant_id = current_setting('app.tenant_id', true)::uuid);

-- === The person of each student record, kept from sis's events (privacy tasks, design PRIVACY-AND-CONSENT-CENTRE §9.1) ===
CREATE TABLE comms.student_record (
    tenant_id uuid NOT NULL,
    student_id uuid NOT NULL,
    person_id uuid NOT NULL,
    user_id uuid,
    institution_id uuid,
    source_version integer NOT NULL,
    synced_at timestamptz NOT NULL,
    CONSTRAINT pk_comms_student_record PRIMARY KEY (tenant_id, student_id),
    CONSTRAINT ck_student_record_source_version CHECK (source_version >= 1)
);
COMMENT ON TABLE comms.student_record IS 'The person, login account and institution of each student record, kept from sis.student created/updated events (comms never reads sis''s schema), so privacy''s tasks find a data principal''s messages, notifications, memberships and posts (CommsPrivacyTaskHandler) and mail and conversations reach only accounts of the sender''s school.';
COMMENT ON COLUMN comms.student_record.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN comms.student_record.student_id IS 'sis.student.id (logical, maintained from its events), as feedback threads, content views and mailbox messages name it.';
COMMENT ON COLUMN comms.student_record.person_id IS 'Person of the student record (people.person.id), the data principal privacy''s tasks name.';
COMMENT ON COLUMN comms.student_record.user_id IS 'Login account of the student record (iam.user_account.id), as recipients, participants, members and authors name it; null while the student has none.';
COMMENT ON COLUMN comms.student_record.institution_id IS 'Institution of the student record (org.institution.id).';
COMMENT ON COLUMN comms.student_record.source_version IS 'Row version of the sis.student row this entry reflects; an event with an older or equal version is ignored.';
COMMENT ON COLUMN comms.student_record.synced_at IS 'When the row was last changed by an event.';
CREATE INDEX ix_comms_student_record_person ON comms.student_record (tenant_id, person_id);
COMMENT ON INDEX comms.ix_comms_student_record_person IS 'Privacy tasks: the student records and login accounts of the data principal.';
ALTER TABLE comms.student_record ENABLE ROW LEVEL SECURITY;
ALTER TABLE comms.student_record FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON comms.student_record USING (tenant_id = current_setting('app.tenant_id', true)::uuid);

CREATE INDEX ix_comms_student_record_user ON comms.student_record (tenant_id, user_id) WHERE user_id IS NOT NULL;
COMMENT ON INDEX comms.ix_comms_student_record_user IS 'Mail and conversations: whether an account is a student of the sender''s school.';
CREATE TABLE comms.staff_record (
    tenant_id uuid NOT NULL,
    staff_id uuid NOT NULL,
    user_id uuid,
    institution_id uuid,
    is_deleted boolean NOT NULL DEFAULT false,
    source_version integer NOT NULL,
    synced_at timestamptz NOT NULL,
    CONSTRAINT pk_comms_staff_record PRIMARY KEY (tenant_id, staff_id),
    CONSTRAINT ck_comms_staff_record_source_version CHECK (source_version >= 1)
);
COMMENT ON TABLE comms.staff_record IS 'The login account and institution of each staff record, kept from hr.staff created/updated/deleted events (comms never reads hr''s schema), so mail and conversations reach only accounts of the sender''s school.';
COMMENT ON COLUMN comms.staff_record.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN comms.staff_record.staff_id IS 'hr.staff.id (logical, maintained from its events).';
COMMENT ON COLUMN comms.staff_record.user_id IS 'Login account of the staff record (iam.user_account.id); NULL while it has none.';
COMMENT ON COLUMN comms.staff_record.institution_id IS 'Institution of the staff record (org.institution.id).';
COMMENT ON COLUMN comms.staff_record.is_deleted IS 'The staff record was deleted in hr; kept so a late event cannot restore it.';
COMMENT ON COLUMN comms.staff_record.source_version IS 'Row version of the hr.staff row this entry reflects; an event with an older or equal version is ignored.';
COMMENT ON COLUMN comms.staff_record.synced_at IS 'When the row was last changed by an event.';
CREATE INDEX ix_comms_staff_record_user ON comms.staff_record (tenant_id, user_id) WHERE NOT is_deleted AND user_id IS NOT NULL;
COMMENT ON INDEX comms.ix_comms_staff_record_user IS 'Mail and conversations: whether an account is staff of the sender''s school.';
ALTER TABLE comms.staff_record ENABLE ROW LEVEL SECURITY;
ALTER TABLE comms.staff_record FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON comms.staff_record USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE comms.guardian_link (
    tenant_id uuid NOT NULL,
    link_id uuid NOT NULL,
    student_id uuid NOT NULL,
    guardian_id uuid NOT NULL,
    guardian_person_id uuid NOT NULL,
    guardian_user_id uuid,
    status varchar(20) NOT NULL,
    is_deleted boolean NOT NULL DEFAULT false,
    source_version integer NOT NULL,
    synced_at timestamptz NOT NULL,
    CONSTRAINT pk_comms_guardian_link PRIMARY KEY (tenant_id, link_id),
    CONSTRAINT ck_comms_guardian_link_source_version CHECK (source_version >= 1)
);
COMMENT ON TABLE comms.guardian_link IS 'Which guardian record, person and login account is linked to which student, kept from sis.student_guardian created/updated/deleted events (comms never reads sis''s schema), so a guardian reaches only the feedback threads opened as them and mail and conversations reach the guardians of the sender''s school.';
COMMENT ON COLUMN comms.guardian_link.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN comms.guardian_link.link_id IS 'sis.student_guardian.id (logical, maintained from its events).';
COMMENT ON COLUMN comms.guardian_link.student_id IS 'sis.student.id of the child.';
COMMENT ON COLUMN comms.guardian_link.guardian_id IS 'sis.guardian.id, as feedback threads name the guardian.';
COMMENT ON COLUMN comms.guardian_link.guardian_person_id IS 'Person of the guardian (people.person.id), matched against the token''s person.';
COMMENT ON COLUMN comms.guardian_link.guardian_user_id IS 'Login account of the guardian when the link was last announced (iam.user_account.id); NULL while it has none.';
COMMENT ON COLUMN comms.guardian_link.status IS 'State of the link in sis; only an active link counts.';
COMMENT ON COLUMN comms.guardian_link.is_deleted IS 'The link was deleted in sis; kept so a late event cannot restore it.';
COMMENT ON COLUMN comms.guardian_link.source_version IS 'Row version of the sis.student_guardian row this entry reflects; an event with an older or equal version is ignored.';
COMMENT ON COLUMN comms.guardian_link.synced_at IS 'When the row was last changed by an event.';
CREATE INDEX ix_comms_guardian_link_guardian ON comms.guardian_link (tenant_id, guardian_id) WHERE NOT is_deleted;
COMMENT ON INDEX comms.ix_comms_guardian_link_guardian IS 'Feedback threads: whether the caller is the thread''s guardian.';
CREATE INDEX ix_comms_guardian_link_user ON comms.guardian_link (tenant_id, guardian_user_id) WHERE NOT is_deleted AND guardian_user_id IS NOT NULL;
COMMENT ON INDEX comms.ix_comms_guardian_link_user IS 'Mail and conversations: whether an account is a guardian of a student of the sender''s school.';
ALTER TABLE comms.guardian_link ENABLE ROW LEVEL SECURITY;
ALTER TABLE comms.guardian_link FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON comms.guardian_link USING (tenant_id = current_setting('app.tenant_id', true)::uuid);

-- === Privacy tasks (design PRIVACY-AND-CONSENT-CENTRE §9.1, §10) and the module's scheduled jobs (core JobSchedule) ===
CREATE TABLE comms.privacy_task_receipt (
    task_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    kind varchar(10) NOT NULL,
    payload jsonb NOT NULL,
    status varchar(15) NOT NULL DEFAULT 'received',
    result jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    CONSTRAINT pk_comms_privacy_task_receipt PRIMARY KEY (task_id),
    CONSTRAINT ck_comms_privacy_task_receipt_kind CHECK (kind IN ('task', 'retention')),
    CONSTRAINT ck_comms_privacy_task_receipt_status CHECK (status IN ('received', 'done', 'partial', 'failed',
        'not_applicable')),
    CONSTRAINT ck_comms_privacy_task_receipt_completed CHECK ((status = 'received') = (completed_at IS NULL))
);
COMMENT ON TABLE comms.privacy_task_receipt IS 'The privacy tasks and retention runs privacy sent this module (privacy.rights_request.task_assigned, privacy.retention.due), one row per task or run id: a task dispatched again runs once, is retried after a failure and is answered again from the stored answer (privacy-client PrivacyTaskHandler). Ids, codes and counts only.';
COMMENT ON COLUMN comms.privacy_task_receipt.task_id IS 'The rights-request task id or the retention run id privacy sent; the id the module answers with.';
COMMENT ON COLUMN comms.privacy_task_receipt.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN comms.privacy_task_receipt.kind IS 'task (a rights-request task) or retention (a retention run).';
COMMENT ON COLUMN comms.privacy_task_receipt.payload IS 'The event''s data as privacy sent it: ids, codes and dates only.';
COMMENT ON COLUMN comms.privacy_task_receipt.status IS 'received (waiting for the module''s job), done, partial, failed or not_applicable.';
COMMENT ON COLUMN comms.privacy_task_receipt.result IS 'The answer published (<module>.privacy_task.completed or <module>.privacy_retention.completed): counts and codes; null while received.';
COMMENT ON COLUMN comms.privacy_task_receipt.created_at IS 'When the task or run first arrived.';
COMMENT ON COLUMN comms.privacy_task_receipt.completed_at IS 'When the module answered; null while received.';
CREATE INDEX ix_comms_privacy_task_receipt_received ON comms.privacy_task_receipt (tenant_id, created_at) WHERE status = 'received';
COMMENT ON INDEX comms.ix_comms_privacy_task_receipt_received IS 'The tasks and runs waiting for the module''s job, the oldest first.';
ALTER TABLE comms.privacy_task_receipt ENABLE ROW LEVEL SECURITY;
ALTER TABLE comms.privacy_task_receipt FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON comms.privacy_task_receipt USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
CREATE TABLE comms.job_schedule (
    job_code varchar(60) NOT NULL,
    tenant_id uuid NOT NULL,
    next_run_at timestamptz NOT NULL,
    lease_owner uuid,
    lease_until timestamptz,
    last_run_at timestamptz,
    failures integer NOT NULL DEFAULT 0,
    last_error varchar(500),
    CONSTRAINT pk_job_schedule PRIMARY KEY (job_code, tenant_id),
    CONSTRAINT ck_job_schedule_lease CHECK ((lease_owner IS NULL) = (lease_until IS NULL)),
    CONSTRAINT ck_job_schedule_failures CHECK (failures >= 0)
);
COMMENT ON TABLE comms.job_schedule IS 'When each tenant is next due for each scheduled job of the module (core JobSchedule, ROADMAP ARC-4). A tenant is enrolled the first time it has work for the job. Job codes, tenant ids and times only, no personal data, and no row-level security: the job runner claims due rows across tenants, then runs each in its tenant''s own context.';
COMMENT ON COLUMN comms.job_schedule.job_code IS 'The job (<module>.<name>): comms.privacy_tasks (runs the privacy tasks and retention runs of comms.privacy_task_receipt).';
COMMENT ON COLUMN comms.job_schedule.tenant_id IS 'The tenant the job runs for.';
COMMENT ON COLUMN comms.job_schedule.next_run_at IS 'When the tenant is next due.';
COMMENT ON COLUMN comms.job_schedule.lease_owner IS 'The runner (a random id per process) holding the tenant''s run; null while no run is held.';
COMMENT ON COLUMN comms.job_schedule.lease_until IS 'Until when the lease holds; after it another runner may take the run over.';
COMMENT ON COLUMN comms.job_schedule.last_run_at IS 'When the last run ended, finished or failed.';
COMMENT ON COLUMN comms.job_schedule.failures IS 'Failed runs in a row; the retry delay doubles with each.';
COMMENT ON COLUMN comms.job_schedule.last_error IS 'Why the last run failed (exception class and message, first 500 characters); null after a finished run.';
CREATE INDEX ix_job_schedule_due ON comms.job_schedule (next_run_at);
COMMENT ON INDEX comms.ix_job_schedule_due IS 'The due runs, the longest overdue first.';

